90	    /// The largest end rate on the 0.001 grid, below `rate`, at which
91	    /// action `action` of `after` reads inside its file: R1's solve, then
92	    /// its step down. `None` when none down to ×0.1 does. Read by R1 and by
93	    /// a split's second half (spec §11 SR-18 (e)).
94	    pub(crate) fn largest_fitting_end_rate(
95	        &self,
96	        after: &Clip,
97	        action: u32,
98	        rate: f64,
99	    ) -> Option<f64> {
100	        let floor = (SPEED_MIN * 1000.0).round() as i64;
101	        self.largest_fitting_rate(&|x| ending_at(after, action, x), rate, floor)
102	    }
103	
104	    /// The largest rate x on the 0.001 grid, below `rate` and at or above
105	    /// `floor_k` thousandths, at which the clip `at_rate(x)` reads inside
106	    /// its file: R1's solve, then its step down. `None` when none does.
107	    /// `at_rate` must make S(D) affine in x — one action's end rate
108	    /// (`largest_fitting_end_rate`), or a preset's target, which every
109	    /// piece it builds ramps to, holds or ramps from (`add_speed_ramp`,
110	    /// spec §11 SR-23 (g)).
111	    pub(crate) fn largest_fitting_rate(
112	        &self,
113	        at_rate: &dyn Fn(f64) -> Clip,
114	        rate: f64,
115	        floor_k: i64,
116	    ) -> Option<f64> {
117	        let probe = at_rate(rate);
118	        let (source_in, file) = self.window_of(&probe)?;
119	        let fits = |x: f64| self.overrun(&at_rate(x)).is_none();
120	        // S(D) = α + β·x in the rate x: read at two rates in range, solved
121	        // for the file's remainder.
122	        let read = |x: f64| SpeedMap::of(&at_rate(x)).map(|m| m.source_at(probe.duration));
123	        let solved = match (read(SPEED_MIN), read(1.0)) {
124	            (Some(low), Some(one)) => {
125	                let beta = (one - low) / (1.0 - SPEED_MIN);
126	                let alpha = low - SPEED_MIN * beta;
127	                let remaining = file.saturating_sub(source_in) as f64;
128	                (beta > 0.0).then(|| (remaining - alpha) / beta)
129	            }
130	            _ => None,
131	        };
132	        let x = solved.filter(|x| x.is_finite())?;
133	        // Floored to 0.001, never at or above the rate that overran, then
134	        // stepped down a thousandth until it fits. The millionth keeps a
135	        // solve that lands a hair under an exact thousandth (×4 read as
136	        // 3.9999999) on it; the step down catches the rest.
137	        let below = (rate * 1000.0).ceil() as i64 - 1;
138	        let mut k = ((x * 1000.0 + 1e-6).floor() as i64).min(below).max(floor_k);
139	        while k >= floor_k {
140	            if fits(thousandths(k)) {
141	                return Some(thousandths(k));
142	            }
143	            k -= 1;
144	        }
145	        None
146	    }
