261	            .into_iter()
262	            .find(|group| group.name() == key)
263	            .ok_or_else(|| unknown_key(key, END_PATCH))?;
264	        // A group set to `null` removes the whole group from the end state,
265	        // which is the same removal one key deep.
266	        if body.is_null() {
267	            continue;
268	        }
269	        check_group_patch(body, group, END_PATCH, key)?;
270	    }
271	    Ok(())
