311	/// The EQ's seven slots, the one group whose slot `off` may name (AU-88).
312	#[rustfmt::skip]
313	const EQ_SLOTS: [&str; 7] =
314	    ["high_pass", "low_shelf", "band_1", "band_2", "band_3", "high_shelf", "low_pass"];
315	
316	/// One `off` path: `group.key`, or `audio.eq.<slot>` with its `slot`.
317	pub(crate) struct OffPath<'a> {
318	    group: &'a str,
319	    key: &'a str,
320	    slot: Option<&'a str>,
321	}
322	
323	/// Reads `set_action_end`'s `off` list (spec §11 CI-14) into its paths,
324	/// refusing in this order: a path that is not `group.key` or
325	/// `audio.eq.<slot>` (AU-88; an unknown slot named against the seven), a
326	/// group an end patch may not name, `video.motion`, `text.words` and
327	/// `video.cutout` (spec §11 CO-20), a path
328	/// `patch` also names, and whatever the group's read says of a `null` there
329	/// — an unknown key, a REQUIRED key (`video.opacity`).
330	pub(crate) fn check_off<'a>(patch: &Value, off: &'a [String]) -> Result<Vec<OffPath<'a>>, String> {
331	    let mut paths = Vec::with_capacity(off.len());
332	    for path in off {
333	        let parts: Vec<&str> = path.split('.').collect();
334	        let (group_name, key, slot) = match parts.as_slice() {
335	            [g, k] if !g.is_empty() && !k.is_empty() => (*g, *k, None),
336	            ["audio", "eq", slot] if EQ_SLOTS.contains(slot) => ("audio", "eq", Some(*slot)),
337	            ["audio", "eq", slot] => {
338	                return Err(format!(
339	                    "off path \"{path}\" names no EQ slot: \"{slot}\" is not one of {}",
340	                    EQ_SLOTS.join(", ")
341	                ))
342	            }
343	            _ => {
344	                return Err(format!(
345	                    "off path \"{path}\" must be \"group.key\", a group of video, audio or \
346	                     text and one of its top-level keys"
347	                ))
348	            }
349	        };
350	        if group_name == "graphic" {
351	            return Err(GRAPHIC_NOT_KEYED_OFF.to_string());
352	        }
353	        let group = END_GROUPS
354	            .into_iter()
355	            .find(|group| group.name() == group_name)
356	            .ok_or_else(|| unknown_key(group_name, END_PATCH))?;
357	        not_a_target(group_name, key)?;
358	        let named = patch.get(group_name).and_then(|body| body.get(key));
359	        if slot
360	            .map_or(named, |slot| named.and_then(|eq| eq.get(slot)))
361	            .is_some()
362	        {
363	            return Err(format!(
364	                "\"{path}\" is named in both the patch and off; an end state cannot both \
365	                 hold it and key it off"
366	            ));
367	        }
368	        let probe = slot.map_or(json!({ key: null }), |slot| json!({ key: { slot: null } }));
369	        let read = match group {
370	            Group::Video => merge_group(&VideoProps::default(), &probe, group).map(|_| ()),
371	            Group::Audio => merge_group(&AudioProps::default(), &probe, group).map(|_| ()),
372	            Group::Text => merge_group(&TextProps::default(), &probe, group).map(|_| ()),
373	            Group::Shape => merge_group(&ShapeProps::default(), &probe, group).map(|_| ()),
374	        };
375	        read.map_err(|why| format!("cannot key \"{path}\" off: {why}"))?;
376	        paths.push(OffPath {
377	            group: group_name,
378	            key,
379	            slot,
380	        });
381	    }
382	    Ok(paths)
383	}
