385	/// The object at `key` of `map`, made `{}` when absent or not an object.
386	fn object_at<'v>(map: &'v mut Map<String, Value>, key: &str) -> Option<&'v mut Map<String, Value>> {
387	    let slot = map
388	        .entry(key.to_string())
389	        .or_insert_with(|| Value::Object(Map::new()));
390	    if !slot.is_object() {
391	        *slot = Value::Object(Map::new());
392	    }
393	    slot.as_object_mut()
394	}
