396	/// Writes `null` at `group.key` of an end state, or at `audio.eq.<slot>`
397	/// (AU-88) — the property keyed OFF. A group or `eq` slot that is not an
398	/// object (`end` is stored as the file had it) is replaced by `{}`.
399	pub(crate) fn key_off(end: &mut Value, path: &OffPath<'_>) {
400	    let Value::Object(groups) = end else {
401	        return;
402	    };
403	    let Some(fields) = object_at(groups, path.group) else {
404	        return;
405	    };
406	    let (target, key) = match path.slot {
407	        Some(slot) => (object_at(fields, path.key), slot),
408	        None => (Some(fields), path.key),
409	    };
410	    if let Some(target) = target {
411	        target.insert(key.to_string(), Value::Null);
412	    }
413	}
