475	//! The model's own colours in action evaluation (spec §11 G-43), beside
476	//! `actions.rs` rather than in it (that file is near the cap).
477	//!
478	//! `actions.rs`'s `lerp` moves every number of an action's state element
479	//! by element, which is right for a position and wrong for a colour. So
480	//! after the spanning action's `lerp`, [`blend_colors`] overwrites each
481	//! colour of the lerped state with the OKLab blend of the action's two
482	//! ends, through `model_color.rs`'s unit path — the arithmetic graphic
483	//! `color` props blend with (G-40), in floating point, never rounded to a
484	//! byte, with straight alpha.
485	//!
486	//! - **By key, never by shape.** The colours are the nine paths below:
487	//!   [`COLOR_POINTERS`]' eight `[r, g, b, a]` and [`CHROMA_KEY_POINTER`]'s
488	//!   `[r, g, b]`. A four-number array anywhere else (a crop is an object; a
489	//!   point is two numbers) is not a colour.
490	//! - **The arity rule.** A key is blended only when both ends hold an array
491	//!   of exactly its arity (4, or 3 for the key) whose every element reads
492	//!   as a number, and the lerped state has a value there. Anything else — a
493	//!   `null`, a missing group, a wrong length, a non-number — keeps what
494	//!   `lerp` produced, which is §5.4's hold-then-switch.
495	//! - **Only a key that moves.** A key whose two ends are equal keeps
496	//!   `lerp`'s exact copy: the OKLab round trip drifts by ~1e-7, and an
497	//!   untouched colour must stay what is stored, mid-action and in a
498	//!   split's second half.
499	//! - **Strictly inside.** Nothing is done unless `0 < u < 1`, so an
500	//!   action's first tick is its start exactly as stored and its end is its
501	//!   end.
502	//! - A non-finite result leaves the lerped value alone.
503	//!
504	//! **The invariant that makes this sound:** no object on a pointer's path
505	//! carries `kind` or `media` (`actions.rs`'s `OBJECT_DISCRIMINANTS`), and
506	//! none sits in a list, so `lerp_at` always walks to each colour (depth
507	//! ≤ 4, under `MAX_PATCH_DEPTH`) and the value overwritten here is that
508	//! walk's, never a whole object held at its start.
509	
510	use serde_json::{Number, Value};
511	
512	use crate::model_color::{oklab_mix_rgb, oklab_mix_unit};
513	
514	/// Every four-channel colour an action's state holds, by key (spec §11 G-43).
515	pub(crate) const COLOR_POINTERS: [&str; 8] = [
516	    "/video/shadow/color",
517	    "/text/color",
518	    "/text/outline/color",
519	    "/text/backdrop/color",
520	    "/text/word_style/active_color",
521	    "/text/word_style/spoken_color",
522	    "/text/word_style/upcoming_color",
523	    "/text/word_style/active_pill/color",
524	];
525	
526	/// `video.chroma.key`, the one three-channel colour (no alpha).
527	pub(crate) const CHROMA_KEY_POINTER: &str = "/video/chroma/key";
528	
529	/// Overwrites each colour in `out` (the lerped state) with the OKLab blend of `from`'s and
530	/// `to`'s values at the same pointer, by eased progress `u`.
531	pub(crate) fn blend_colors(from: &Value, to: &Value, u: f64, out: &mut Value) {
532	    let inside = u > 0.0 && u < 1.0;
533	    if !inside {
534	        return;
535	    }
536	    for pointer in COLOR_POINTERS {
537	        if let Some((a, b)) = ends::<4>(from, to, pointer) {
538	            write(out, pointer, &oklab_mix_unit(a, b, u));
539	        }
540	    }
541	    if let Some((a, b)) = ends::<3>(from, to, CHROMA_KEY_POINTER) {
542	        write(out, CHROMA_KEY_POINTER, &oklab_mix_rgb(a, b, u));
543	    }
544	}
