546	/// The two ends at `pointer` as colours of arity `N`, or `None` when
547	/// either does not read as one or they are the same numbers (compared
548	/// parsed, so a stored `1.0` and an end's `1` are one colour).
549	fn ends<const N: usize>(from: &Value, to: &Value, pointer: &str) -> Option<([f64; N], [f64; N])> {
550	    let a = channels::<N>(from.pointer(pointer)?)?;
551	    let b = channels::<N>(to.pointer(pointer)?)?;
552	    (a != b).then_some((a, b))
553	}
