555	/// An array of exactly `N` numbers.
556	fn channels<const N: usize>(value: &Value) -> Option<[f64; N]> {
557	    let list = value.as_array()?;
558	    if list.len() != N {
559	        return None;
560	    }
561	    let mut out = [0.0; N];
562	    for (slot, element) in out.iter_mut().zip(list) {
563	        *slot = element.as_f64()?;
564	    }
565	    Some(out)
566	}
