568	/// Writes `channels` as floats at `pointer`, when `out` has a value there
569	/// and every channel is finite.
570	fn write(out: &mut Value, pointer: &str, channels: &[f64]) {
571	    let Some(numbers) = channels
572	        .iter()
573	        .map(|&v| Number::from_f64(v).map(Value::Number))
574	        .collect::<Option<Vec<Value>>>()
575	    else {
576	        return;
577	    };
578	    if let Some(slot) = out.pointer_mut(pointer) {
579	        *slot = Value::Array(numbers);
580	    }
581	}
582	//! The curves' JSON helpers for action evaluation (spec §11 GR-12, GR-34),
583	//! beside `actions.rs` rather than in it (that file is near the cap).
584	//!
585	//! [`curves_json`] writes all six channels, an absent one as its domain's
586	//! identity ([`IDENTITY_CURVE`], `IDENTITY_HUE_SHIFT`, `IDENTITY_HUE_GAIN`,
587	//! spec §11 GR-32), for every reader of `actions::video_json`: the state an
588	//! action interpolates from, the patch template (so `curves.red` is a known
589	//! key) and `split`'s state. [`align_identity_curves`] is the one rule the
590	//! list rule needs to animate a grade from neutral: an identity channel
591	//! meeting a curve of a different count takes that curve's x's — on a tone
592	//! curve with y = x and its ends at `[0, 0]` and `[1, 1]`, on a hue curve
593	//! with the neutral value — so the two lists match and interpolate per
594	//! point.
595	//!
596	//! Any other count change — two non-identity curves of different point
597	//! counts — BLENDS their values (GR-34): the list rule holds the list at its
598	//! start value `a`, so the evaluated props hold `a`, and [`curve_blends`]
599	//! names each such channel with the end curve `b` and the eased progress t.
600	//! [`blended_curves_json`] writes the recipe's and `clip_state`'s `curves`
601	//! with each blended channel as `{from, to, t}`, which Swift's strip samples
602	//! as `(1 − t)·a(x) + t·b(x)`. The core never samples a spline; a blend is
603	//! never written to a file (the model, a split, a paste and the template
604	//! hold points through [`curves_json`]).
