612	/// One channel blended inside an action (spec §11 GR-34): its held curve
613	/// `from`, the action's clamped end curve `to`, both non-identity and of
614	/// different point counts, and the eased progress `t`, strictly inside 0…1.
615	#[derive(Debug, Clone, PartialEq)]
616	pub struct CurveBlend {
617	    pub channel: &'static str,
618	    pub from: Vec<CurvePoint>,
619	    pub to: Vec<CurvePoint>,
620	    pub t: f64,
621	}
