623	/// The channels to blend at eased progress `t`: one per channel, in model
624	/// order, where `held` (the evaluated, clamped curves) and the action's
625	/// merged `target` (its `video.curves` decoded and clamped as an end is) are
626	/// both non-identity with different point counts. Empty unless 0 < t < 1,
627	/// and when the target's curves do not decode.
628	pub(crate) fn curve_blends(held: &Curves, target: &Value, t: f64) -> Vec<CurveBlend> {
629	    if t.is_nan() || t <= 0.0 || t >= 1.0 {
630	        return Vec::new();
631	    }
632	    let Some(value) = target.get("video").and_then(|video| video.get("curves")) else {
633	        return Vec::new();
634	    };
635	    let Ok(mut ends) = serde_json::from_value::<Curves>(value.clone()) else {
636	        return Vec::new();
637	    };
638	    clamp_curves(&mut ends);
639	    let mut out = Vec::new();
640	    for ((channel, _, from), (_, _, to)) in held.named().into_iter().zip(ends.named()) {
641	        if let (Some(from), Some(to)) = (from, to) {
642	            if from.len() == to.len() {
643	                continue;
644	            }
645	            out.push(CurveBlend {
646	                channel,
647	                from: from.clone(),
648	                to: to.clone(),
649	                t,
650	            });
651	        }
652	    }
653	    out
654	}
