666	            fields.insert("to".to_string(), to_json(&blend.to));
667	            fields.insert("t".to_string(), to_json(&blend.t));
668	            channels.insert(blend.channel.to_string(), Value::Object(fields));
669	        }
670	    }
671	    out
672	}
