693	/// The identity on `other`'s x's: on a tone curve its first point `[0, 0]`,
694	/// its last `[1, 1]`, every point between at y = x; on a hue curve every
695	/// point at the neutral value.
696	fn aligned(other: &[CurvePoint], domain: CurveDomain) -> Value {
697	    let last = other.len().saturating_sub(1);
698	    let out: Vec<CurvePoint> = other
699	        .iter()
700	        .enumerate()
701	        .map(|(index, point)| {
702	            if let Some(neutral) = domain.neutral() {
703	                [point[0], neutral]
704	            } else if index == 0 {
705	                [0.0, 0.0]
706	            } else if index == last {
707	                [1.0, 1.0]
708	            } else {
709	                [point[0], point[0]]
710	            }
711	        })
712	        .collect();
713	    to_json(&out)
714	}
