845	        if !patch.is_object() {
846	            return Err(format!(
847	                "action end patch must be a json object, not {}",
848	                describe(patch)
849	            ));
850	        }
851	        if let Some(schema) = schema {
852	            check_schema(schema)?;
853	        }
854	        // Present at all — a `null` included, since writing `motion: null`
855	        // into an end patch is still asking an action to decide a preset.
856	        for (group, key) in [
857	            ("video", "motion"),
858	            ("video", "hide_silent"),
859	            ("text", "words"),
860	        ] {
861	            if patch.get(group).and_then(|body| body.get(key)).is_some() {
862	                not_a_target(group, key)?;
